    arr2.sort()

    min_diff = float('inf')
    pair = ()

    for num1 in arr1:
        idx = binary_search(arr2, num1)
        if idx > 0 and abs(arr2[idx-1]-num1) < min_diff:
            min_diff = abs(arr2[idx-1]-num1)
            pair = (arr2[idx-1], num1)
        if idx < len(arr2) and abs(arr2[idx]-num1) < min_diff:
            min_diff = abs(arr2[idx]-num1)
            pair = (arr2[idx], num1)

