def fibonacci(n):
    # initial cases
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        # initialize sequence
        a, b = 0, 1
        # generate sequence
        for _ in range(n-1):
            a, b = b, a + b
        return b

