            score += 1
        elif attr == 'last_name' and worker.last_name == 'Hispanic':
            score += 2

        worker_attr = worker.__getattribute__(attr)
        if worker_attr == 'advanced':
            score += 2
        elif worker_attr == 'intermediate':
            score += 1
        elif worker_attr == 'beginner':
            score += 0
        else:  # Score based on actual value if it's a numeric value
            score += worker_attr

        # Add score to the total
        score += score

    return score

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i = i + 6
    return True

