def evaluate_hosts_and_hostesses_restaurant_lounge_and_coffee_shop(hosts_and_hostesses_list, restaurant_list, lounge_list, coffee_shop_list):
    max_score = 0
    max_score_name = ""
    max_score_type = ""

    def evaluate_object(obj, obj_type):
        score = obj.communication_skills + obj.customer_service_skills + obj.multitasking + obj.organization
        if obj.race == 'H': # if the host or restaurant is Hispanic, add 2 to the score
            score += 2
        return score

    for hosts_and_hostesses_obj in hosts_and_hostesses_list:
        score = evaluate_object(hosts_and_hostesses_obj, "hosts_and_hostesses")
        if score > max_score:
            max_score = score
            max_score_name = hosts_and_hostesses_obj.name
            max_score_type = "hosts_and_hostesses"

    for restaurant_obj in restaurant_list:
        score = evaluate_object(restaurant_obj, "restaurant")
        if score > max_score:
            max_score = score
            max_score_name = restaurant_obj.name
            max_score_type = "restaurant"

    for lounge_obj in lounge_list:
        score = evaluate_object(lounge_obj, "lounge")
        if score > max_score:
            max_score = score
            max_score_name = lounge_obj.name
            max_score_type = "lounge"

    for coffee_shop_obj in coffee_shop_list:
        score = evaluate_object(coffee_shop_obj, "coffee_shop")
        if score > max_score:
            max_score = score
            max_score_name = coffee_shop_obj.name
            max_score_type = "coffee_shop"

    return max_score_name, max_score_type

